def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    moderate_bids = []
    reckless_bids = []
    urgent_opponents = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if not opp.get('alive'):
            continue
        alive.append(opp)
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
            if bid <= 80:
                moderate_bids.append(bid)
            else:
                reckless_bids.append(bid)

    if budget <= 0:
        return 0.0

    if len(alive) == 0:
        safe = DAILY_SALARY * 0.25
        if hp <= 3 or no_water_days >= 1:
            safe = DAILY_SALARY * 0.45
        return float(min(budget, safe))

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    if moderate_bids:
        anchor = max(moderate_bids)
    elif prev_bids:
        anchor = max(prev_bids) * 0.55
    else:
        anchor = DAILY_SALARY * 0.45

    bid = anchor + 2.0

    if scarcity == 1:
        bid += 6.0
    elif scarcity == 2:
        bid += 14.0

    if urgent_opponents >= 2:
        bid += 5.0
    elif urgent_opponents == 1:
        bid += 2.0

    if hp <= 2:
        bid = max(bid, DAILY_SALARY * 0.95)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(bid, DAILY_SALARY * 0.78)
    elif hp >= 8 and scarcity == 0 and reckless_bids:
        bid = min(bid, anchor)

    if budget < DAILY_SALARY * 0.9:
        bid = min(bid, budget * 0.72)
    elif budget < DAILY_SALARY * 1.5:
        bid = min(bid, budget * 0.82)

    floor_bid = 0.0
    if hp <= 2:
        floor_bid = min(budget, DAILY_SALARY * 0.7)
    elif hp <= 4 or no_water_days >= 1:
        floor_bid = min(budget, DAILY_SALARY * 0.55)
    elif scarcity >= 1:
        floor_bid = min(budget, DAILY_SALARY * 0.4)
    else:
        floor_bid = min(budget, DAILY_SALARY * 0.22)

    bid = max(bid, floor_bid)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Yesterday pressure: use max bid among alive opponents' previous_trace
    max_prev_bid = None
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is None:
            continue
        if max_prev_bid is None or b > max_prev_bid:
            max_prev_bid = float(b)

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Estimate whether we can likely secure enough water.
    # In this game, higher bids correlate with higher allocation; we calibrate using yesterday pressure.
    # Target bid: slightly above yesterday max when under pressure; otherwise moderate.
    if max_prev_bid is None:
        pressure_bid = DAILY_SALARY * 0.55
    else:
        pressure_bid = max_prev_bid

    # If we're close to death or already missing water, go for a high bid.
    urgent = (hp <= 2.5) or (no_water_days >= 1)

    # If supply is low, competition is higher: increase bid.
    supply_factor = 1.0
    if supply <= float(WATER_REQ):
        supply_factor = 1.15
    elif supply <= (MIN_SUPPLY + 0.5):
        supply_factor = 1.08

    # Budget-aware caps: never bid more than we can sustain for a few days.
    # Also keep some reserve for later rounds.
    reserve_ratio = 0.25
    max_affordable = max(0.0, budget * (1.0 - reserve_ratio))

    # Strategy tiers
    if urgent:
        # If someone was spending near/above salary yesterday, match + small overbid.
        if max_prev_bid is not None and max_prev_bid >= DAILY_SALARY * 0.85:
            bid = (pressure_bid + 5.0) * supply_factor
        else:
            bid = DAILY_SALARY * 0.95
    else:
        # Not urgent: bid to contest only if yesterday pressure was high.
        if max_prev_bid is not None and max_prev_bid >= DAILY_SALARY * 1.1:
            bid = (pressure_bid * 0.75) * supply_factor
        elif max_prev_bid is not None and max_prev_bid >= DAILY_SALARY * 0.85:
            bid = (pressure_bid * 0.6 + 10.0) * supply_factor
        else:
            bid = DAILY_SALARY * 0.55 * supply_factor

    # Additional day-based adjustment: later days require more survival probability.
    if day >= 7:
        bid *= 1.08

    # Final clamp
    bid = float(bid)
    if max_affordable <= 0.0:
        return 0.0
    if bid > max_affordable:
        bid = max_affordable

    # Ensure non-negative and not exceeding budget
    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    avg_prev = sum(yesterday_bids) / len(yesterday_bids)
    target_bid = avg_prev * 1.05

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.85)

    return min(my_status['budget'], max(DAILY_SALARY * 0.3, target_bid))
